CREATE TABLE IF NOT EXISTS uplinks (received_at INTEGER NOT NULL, dev_eui TEXT NOT NULL, rssi INTEGER, snr REAL, payload TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS uplinks_time ON uplinks (received_at);

CREATE TABLE IF NOT EXISTS hours (hour INTEGER PRIMARY KEY, n INTEGER NOT NULL, temperature REAL NOT NULL, conductivity REAL NOT NULL, turbidity REAL NOT NULL, fluorescenceRaw REAL NOT NULL, fluorescence REAL NOT NULL, s0 REAL NOT NULL, s1 REAL NOT NULL, s2 REAL NOT NULL, s3 REAL NOT NULL, s4 REAL NOT NULL, s5 REAL NOT NULL, s6 REAL NOT NULL, s7 REAL NOT NULL, s8 REAL NOT NULL, s9 REAL NOT NULL, s10 REAL NOT NULL, s11 REAL NOT NULL, s12 REAL NOT NULL, s13 REAL NOT NULL, s14 REAL NOT NULL, s15 REAL NOT NULL, s16 REAL NOT NULL, s17 REAL NOT NULL);
